194	/**
195	 * Compute hours from actual generated module durations rather than using the
196	 * user's input target hours. This ensures the summary reflects what was
197	 * actually generated, not what was requested — critical when token truncation
198	 * causes the AI to generate fewer modules than planned.
199	 *
200	 * Exported for use by the Inngest curriculumBuilder background job.
201	 */
202	export function computeHoursFromStages(
203	  stages: unknown[],
204	): CurriculumSummary['hours'] {
205	  type ModShape = { eventType?: string; duration?: number };
206	  type StageShape = { modules?: ModShape[] };
207	
208	  const allMods = (stages as StageShape[]).flatMap((s) => s.modules ?? []);
209	  let flightMin = 0;
210	  let soloMin = 0;
211	  let simMin = 0;
212	  let groundMin = 0;
213	
214	  for (const m of allMods) {
215	    const dur = m.duration ?? 0;
216	    const et = (m.eventType ?? '').toLowerCase();
217	    if (et === 'flight lesson') flightMin += dur;
218	    else if (et === 'solo flight') soloMin += dur;
219	    else if (et === 'sim lesson') simMin += dur;
220	    else if (et === 'ground lesson') groundMin += dur;
221	    // Stage/final checks count as flight time
222	    else if (et === 'stage check' || et === 'final check') flightMin += dur;
223	  }
224	
225	  const toHours = (min: number) => Math.round((min / 60) * 10) / 10;
226	  const flight = toHours(flightMin);
227	  const solo = toHours(soloMin);
228	  const sim = toHours(simMin);
229	  const ground = toHours(groundMin);
230	  return {
231	    flight,
232	    solo,
233	    sim,
234	    ground,
235	    total: Math.round((flight + solo + sim + ground) * 10) / 10,
236	  };
237	}
