239	export function getFARMinimums(
240	  programType: ProgramType,
241	  framework: RegulatoryFramework,
242	): { total: number; dual: number; solo: number; sim: number; ground: number } {
243	  if (framework === 'Part 141') {
244	    if (programType === 'Private Pilot (PPL)')
245	      return { total: 35, dual: 20, solo: 10, sim: 2.5, ground: 5 };
246	    if (programType === 'Instrument Rating (IR)')
247	      return { total: 35, dual: 15, solo: 0, sim: 10, ground: 5 };
248	    if (programType === 'Commercial Pilot (CPL)')
249	      return { total: 120, dual: 55, solo: 10, sim: 25, ground: 10 };
250	  }
251	  // Part 61
252	  if (programType === 'Private Pilot (PPL)')
253	    return { total: 40, dual: 20, solo: 10, sim: 2.5, ground: 3 };
254	  if (programType === 'Instrument Rating (IR)')
255	    return { total: 40, dual: 15, solo: 0, sim: 20, ground: 3 };
256	  if (programType === 'Commercial Pilot (CPL)')
257	    return { total: 250, dual: 100, solo: 100, sim: 50, ground: 10 };
258	  return { total: 40, dual: 20, solo: 10, sim: 2.5, ground: 3 };
259	}
