262	  if (programType === 'Private Pilot (PPL)') {
263	    return [
264	      'PA.I — Preflight Preparation',
265	      'PA.II — Preflight Procedures',
266	      'PA.III — Airport and Airspace Operations',
267	      'PA.IV — Takeoffs, Landings, and Go-Arounds',
268	      'PA.V — Performance and Ground Reference Maneuvers',
269	      'PA.VI — Navigation',
270	      'PA.VII — Slow Flight and Stalls',
271	      'PA.VIII — Basic Instrument Maneuvers',
272	      'PA.IX — Emergency Operations',
273	      'PA.X — Night Operations',
274	      'PA.XI — Postflight Procedures',
275	    ];
276	  }
277	  if (programType === 'Instrument Rating (IR)') {
278	    return [
279	      'IR.I — Preflight Preparation',
280	      'IR.II — Preflight Procedures',
281	      'IR.III — Air Traffic Control Clearances and Procedures',
282	      'IR.IV — Flight by Reference to Instruments',
283	      'IR.V — Navigation Systems',
284	      'IR.VI — Instrument Approach Procedures',
285	      'IR.VII — Emergency Operations',
286	      'IR.VIII — Postflight Procedures',
287	    ];
288	  }
289	  if (programType === 'Commercial Pilot (CPL)') {
290	    return [
291	      'CA.I — Preflight Preparation',
292	      'CA.II — Preflight Procedures',
293	      'CA.III — Airport and Airspace Operations',
294	      'CA.IV — Takeoffs, Landings, and Go-Arounds',
295	      'CA.V — Performance Maneuvers',
296	      'CA.VI — Ground Reference Maneuvers',
297	      'CA.VII — Navigation',
298	      'CA.VIII — Slow Flight and Stalls',
299	      'CA.IX — Basic Instrument Maneuvers',
300	      'CA.X — Emergency Operations',
301	      'CA.XI — Night Operations',
302	      'CA.XII — Postflight Procedures',
303	    ];
304	  }
305	  return ['ACS areas per FAA standards'];
306	}
