308	export function buildCurriculumPrompt(params: BuilderParams): string {
309	  const farMins = getFARMinimums(
310	    params.programType,
311	    params.regulatoryFramework,
312	  );
313	  const acsAreas = getACSAreas(params.programType);
314	  const isElite = params.qualityLevel === 'Elite';
315	  const cc = params.contentCustomization;
316	  const ac = params.assignmentConfig;
317	  const rc = params.resourceConfig;
318	  const md = params.moduleDescriptions;
319	
320	  // Determine module depth from customization or quality level defaults
321	  const topicsRange =
322	    cc?.topicsCovered === false
323	      ? 'no topics list'
324	      : cc?.topicDetailLevel === 'Summary'
325	        ? '3-5 topics'
326	        : cc?.topicDetailLevel === 'Detailed'
327	          ? '15+ topics'
328	          : isElite
329	            ? '8-12 topics'
330	            : '5-8 topics';
331	
332	  const tasksDepth =
333	    cc?.lessonTasks === false
334	      ? 'no lesson tasks'
335	      : cc?.taskDepth === 'Brief'
336	        ? '2-3 lesson tasks (objective only)'
337	        : cc?.taskDepth === 'Comprehensive'
338	          ? '5-7 lesson tasks with full ACS standards and detailed descriptions'
339	          : isElite
340	            ? '4-6 lesson tasks with ACS references'
341	            : '3-4 lesson tasks';
342	
343	  const assignmentsRange =
344	    ac?.enabled === false
345	      ? 'no assignments'
346	      : ac?.perModule === '1-2'
347	        ? '1-2 assignments'
348	        : ac?.perModule === '3-5'
349	          ? '3-5 assignments'
350	          : isElite
351	            ? '2-3 assignments'
352	            : '1-2 assignments';
353	
354	  const resourcesRange =
355	    rc?.enabled === false
356	      ? 'no resources'
357	      : rc?.perModule === '2-3'
358	        ? '2-3 resources'
359	        : rc?.perModule === '5-8'
360	          ? '5-8 resources'
361	          : isElite
362	            ? '3-5 resources'
363	            : '2-3 resources';
364	
365	  const moduleDepth = `${topicsRange}, ${tasksDepth}, ${assignmentsRange}, ${resourcesRange}`;
366	
367	  // Sequencing rules
368	  const seqRules = params.sequencingRules;
369	  const sequencingSection = [
370	    seqRules?.enforceGroundBeforeFlight !== false
371	      ? '- Ground lessons ALWAYS before flight lessons covering the same topic'
372	      : null,
373	    '- Ground on airspace BEFORE first solo; Ground on weather BEFORE first cross-country',
374	    '- Sim sessions BEFORE the corresponding flight lessons',
375	    seqRules?.gateSolosBehindEndorsements !== false
376	      ? '- All pre-solo endorsement requirements met before first solo flight'
377	      : null,
378	    seqRules?.stageChecksAtEnd !== false
379	      ? '- Stage checks at the END of each stage as a gate to progression'
380	      : null,
381	    seqRules?.checkrideReadinessReview !== false
382	      ? '- Checkride readiness review at end of final stage'
383	      : null,
384	    '- Night ground BEFORE night flight; Instrument ground BEFORE hood work',
385	  ]
386	    .filter(Boolean)
387	    .join('\n');
388	
389	  // Content instructions based on customization
390	  const contentInstructions: string[] = [];
391	  if (cc) {
392	    if (cc.lessonTasks && cc.taskDepth === 'Brief') {
393	      contentInstructions.push(
394	        'Lesson tasks: include objective only (brief format)',
395	      );
396	    } else if (cc.lessonTasks && cc.taskDepth === 'Comprehensive') {
397	      contentInstructions.push(
398	        'Lesson tasks: include full objective, knowledge standards, risk management, and skill/performance standards',
399	      );
400	    }
401	    if (cc.acsReferenceCodes)
402	      contentInstructions.push('Include ACS reference codes on lesson tasks');
403	    if (!cc.farRefs) contentInstructions.push('SKIP FAR references');
404	    if (!cc.aimRefs) contentInstructions.push('SKIP AIM references');
405	    if (cc.notamGuidance)
406	      contentInstructions.push('Include NOTAM/TFR guidance where relevant');
407	    if (cc.advisoryCirculars)
408	      contentInstructions.push('Include advisory circular references');
409	    if (!cc.mapEndorsements)
410	      contentInstructions.push('SKIP endorsement mappings');
411	  }
412	
413	  // Assignment instructions
414	  const assignmentInstructions: string[] = [];
415	  if (ac?.enabled) {
416	    const types = Object.entries(ac.types)
417	      .filter(([, v]) => v)
418	      .map(([k]) => k)
419	      .join(', ');
420	    if (types)
421	      assignmentInstructions.push(`Assignment types to include: ${types}`);
422	    if (ac.dueDateMode === 'before') {
423	      assignmentInstructions.push(
424	        `Assignments due ${ac.daysBefore} day(s) BEFORE the lesson`,
425	      );
426	    } else if (ac.dueDateMode === 'after') {
427	      assignmentInstructions.push(
428	        `Assignments due ${ac.daysAfter} day(s) AFTER the lesson`,
429	      );
430	    }
431	    if (ac.completionCriteria)
432	      assignmentInstructions.push('Include completion criteria per assignment');
433	  }
434	
435	  // Resource instructions
436	  const resourceInstructions: string[] = [];
437	  if (rc?.enabled) {
438	    if (!rc.types.thirdPartyVideo)
439	      resourceInstructions.push(
440	        "EXCLUDE third-party video resources (YouTube, Sporty's, etc.)",
441	      );
442	    if (!rc.types.poh)
443	      resourceInstructions.push('EXCLUDE manufacturer POH/AFM references');
444	    if (!rc.types.studyGuides)
445	      resourceInstructions.push('EXCLUDE commercial study guide references');
446	    if (rc.linkPolicy === 'verified')
447	      resourceInstructions.push(
448	        'Use ONLY verified gov URLs (faa.gov, ecfr.gov, aviationweather.gov) — empty string for unverifiable URLs',
449	      );
450	  }
451	
452	  const customizationBlock = [
453	    ...contentInstructions,
454	    ...assignmentInstructions,
455	    ...resourceInstructions,
456	    md?.enabled === false ? 'SKIP module descriptions' : null,
457	    md?.length === 'Brief' ? 'Module descriptions: 1-2 sentences only' : null,
458	    md?.length === 'Detailed'
459	      ? 'Module descriptions: 2-3 paragraphs with learning context'
460	      : null,
461	  ].filter(Boolean);
462	
463	  const simClause =
464	    params.trainingEnvironment.ftd || params.trainingEnvironment.ffs
465	      ? `Include ${params.targetHours.sim}h simulator time (up to ${farMins.sim}h credit toward minimums). Sim sessions practice procedures before flight.`
466	      : 'No simulator in training environment.';
467	
468	  const school = params.schoolName
469	    ? `School: ${params.schoolName}`
470	    : 'General flight school';
471	  const airport = params.baseAirport
472	    ? `Base airport: ${params.baseAirport}`
473	    : '';
474	
475	  return `You are an expert FAA flight training curriculum designer. Build a complete ${params.regulatoryFramework} ${params.programType} curriculum for ${school}${airport ? ` at ${airport}` : ''}.
476	
477	AIRCRAFT CATEGORY: ${params.aircraftCategory}
478	REGULATORY FRAMEWORK: ${params.regulatoryFramework}
479	TARGET HOURS: ${params.targetHours.total}h total (${params.targetHours.dual}h dual, ${params.targetHours.solo}h solo, ${params.targetHours.sim}h sim, ${params.targetHours.ground}h ground)
480	FAR MINIMUMS: ${farMins.total}h total, ${farMins.dual}h dual, ${farMins.solo}h solo, ${farMins.sim}h sim, ${farMins.ground}h ground
481	TRAINING STYLE: ${params.trainingStyle}
482	STAGES: ${params.stageCount}
483	QUALITY: ${params.qualityLevel} (${moduleDepth})
484	${simClause}
485	${customizationBlock.length > 0 ? `\nCUSTOMIZATION INSTRUCTIONS:\n${customizationBlock.map((i) => `- ${i}`).join('\n')}` : ''}
486	
487	ACS AREAS TO COVER: ${acsAreas.join(', ')}
488	
489	CRITICAL SEQUENCING RULES:
490	${sequencingSection}
491	
492	MODULE TYPES: Use "Ground Lesson", "Sim Lesson", "Flight Lesson", "Solo Flight", "Stage Check", "Final Check"
493	
494	Return ONLY valid JSON (no markdown, no explanation) with this exact structure:
495	{
496	  "title": "${params.programType} — ${params.regulatoryFramework} — ${params.aircraftCategory}",
497	  "description": "Complete FAA-compliant ${params.programType} curriculum under ${params.regulatoryFramework} for ${params.aircraftCategory}",
498	  "category": "${params.programType}",
499	  "stages": [
500	    {
501	      "name": "Stage 1 — <stage_name>",
502	      "description": "<stage_goal>",
503	      "modules": [
504	        {
505	          "title": "<module_title>",
506	          "eventType": "Ground Lesson|Sim Lesson|Flight Lesson|Solo Flight|Stage Check|Final Check",
507	          "duration": <minutes_integer>,
508	          "preBrief": <minutes_integer>,
509	          "debrief": <minutes_integer>,
510	          "description": "<module_purpose>",
511	          "topics": [
512	            { "text": "<topic_text>", "sortOrder": 0 }
513	          ],
514	          "lessonTasks": [
515	            {
516	              "title": "<task_title>",
517	              "completionStandard": "<ACS standard or performance criterion>",
518	              "sortOrder": 0
519	            }
520	          ],
521	          "assignments": [
522	            {
523	              "title": "<assignment_title>",
524	              "type": "Reading|Quiz|Written|Video|Oral",
525	              "objective": "<what student will learn>"
526	            }
527	          ],
528	          "resources": [
529	            {
530	              "title": "<resource_title>",
531	              "type": "Document|Video|Website|Tool",
532	              "url": "<actual_gov_or_official_url_or_empty_string>"
533	            }
534	          ],
535	          "regulations": [
536	            { "text": "<regulation_text_with_citation>", "sortOrder": 0 }
537	          ],
538	          "endorsements": [
539	            { "text": "<endorsement_text_with_FAR_citation>", "sortOrder": 0 }
540	          ]
541	        }
542	      ]
543	    }
544	  ],
545	  "summary": {
546	    "stageCount": ${params.stageCount},
547	    "groundModules": <count>,
548	    "simModules": <count>,
549	    "flightModules": <count>,
550	    "soloModules": <count>,
551	    "checkModules": <count>,
552	    "hours": {
553	      "flight": <dual_flight_hours>,
554	      "solo": <solo_hours>,
555	      "sim": <sim_hours>,
556	      "ground": <ground_instruction_hours>,
557	      "total": <total_hours>
558	    },
559	    "farCompliance": [
560	      { "requirement": "Total flight time", "minimum": ${farMins.total}, "actual": <actual>, "status": "pass|fail", "citation": "14 CFR ${params.regulatoryFramework === 'Part 141' ? 'Part 141 App B' : '61.109'}" }
561	    ],
562	    "acsCoverage": [${acsAreas.map((a) => `"${a.split(' — ')[0]}"`).join(', ')}],
563	    "endorsements": [
564	      { "regulation": "FAR 61.87(b)", "title": "Pre-Solo Knowledge Test", "mappedToModule": "<module_title>" }
565	    ],
566	    "stats": {
567	      "assignments": <total_count>,
568	      "resources": <total_count>,
569	      "tasks": <total_count>,
570	      "regulations": <total_count>
571	    }
572	  }
573	}
574	
575	Generate all ${params.stageCount} stages with complete modules. Use only verified FAA gov URLs (faa.gov, ecfr.gov, aviationweather.gov) — use empty string for URLs you cannot verify. The curriculum must pass FAR compliance checks.`;
576	}
