585	// ─── Routes ───────────────────────────────────────────────────────────────────
586	
587	/**
588	 * POST /ai-curriculum/build
589	 *
590	 * Enqueue a background curriculum generation job via Inngest.
591	 * Returns {jobId} immediately (HTTP 202) so the browser is not blocked.
592	 * The client polls GET /ai-curriculum/build-status/:jobId to track progress.
593	 *
594	 * This replaces the previous SSE streaming approach which was session-bound:
595	 * any page refresh or tab close would kill the build. The Inngest background
596	 * job runs entirely server-side with no browser session dependency.
597	 */
598	aiCurriculumBuilder.post('/ai-curriculum/build', requireAuth(), async (c) => {
599	  if (!getAnthropicKey('curriculum-builder')) {
600	    return c.json({ error: 'AI service not configured' }, 503);
601	  }
602	
603	  let body: BuilderParams;
604	  try {
605	    body = await c.req.json();
606	  } catch {
607	    return c.json({ error: 'Invalid request body' }, 400);
608	  }
609	
610	  if (!body.programType || !body.regulatoryFramework || !body.locationId) {
611	    return c.json(
612	      {
613	        error: 'programType, regulatoryFramework, and locationId are required',
614	      },
615	      400,
616	    );
617	  }
618	
619	  const authUser = c.get('authUser') as AuthUser;
620	  const orgId = await resolveOrgIdFromSession(authUser, c);
621	  if (!orgId) return c.json({ error: 'Could not resolve organization' }, 403);
622	
623	  // Create the job record
624	  const [job] = await db
625	    .insert(curriculumBuildJobs)
626	    .values({
627	      flightSchoolId: orgId,
628	      userId: authUser.id,
