149	function computeHours(stages: CurriculumStage[]): {
150	  flight: number;
151	  ground: number;
152	  sim: number;
153	} {
154	  let flight = 0;
155	  let ground = 0;
156	  let sim = 0;
157	  for (const stage of stages) {
158	    for (const m of stage.modules) {
159	      const dur = Number(m.duration) || 0;
160	      const pre = Number(m.preBrief) || 0;
161	      const deb = Number(m.debrief) || 0;
162	      const et = (m.eventType || '').toLowerCase();
163	      if (
164	        et.includes('flight') ||
165	        et === 'stage check' ||
166	        et === 'practical test'
167	      ) {
168	        flight += dur;
169	      } else if (et.includes('ground')) {
170	        ground += dur;
171	      } else if (et.includes('sim') || et.includes('simulator')) {
172	        sim += dur;
173	      } else {
174	        flight += dur;
175	      }
176	      ground += pre + deb;
177	    }
178	  }
179	  return {
180	    flight: Math.round((flight / 60) * 10) / 10,
181	    ground: Math.round((ground / 60) * 10) / 10,
182	    sim: Math.round((sim / 60) * 10) / 10,
183	  };
184	}
