186	function buildCurriculumSummary(curriculum: CurriculumInput): string {
187	  const certificateRating =
188	    curriculum.certificateRatingName || curriculum.category || 'Not specified';
189	  const lines: string[] = [
190	    `CURRICULUM: ${curriculum.title}`,
191	    `Certificate / Rating: ${certificateRating}`,
192	    `ACS Key: ${curriculum.certificateRatingAcsKey || 'Not specified'}`,
193	    `Level: ${curriculum.level || 'Not specified'}`,
194	    `Description: ${curriculum.description || 'None'}`,
195	    `Total Stages: ${curriculum.stages.length}`,
196	    '',
197	  ];
198	
199	  for (const stage of curriculum.stages) {
200	    lines.push(`STAGE: ${stage.name}`);
201	    if (stage.description) lines.push(`  Description: ${stage.description}`);
202	    lines.push(`  Modules (${stage.modules.length}):`);
203	    for (const m of stage.modules) {
204	      const dur = Number(m.duration) || 0;
205	      const pre = Number(m.preBrief) || 0;
206	      const deb = Number(m.debrief) || 0;
207	      lines.push(
208	        `    - [${m.moduleType}] ${m.title} (${m.eventType || 'unknown type'}, ${dur}min + ${pre}min pre + ${deb}min debrief)`,
209	      );
210	      if (m.topics && m.topics.length > 0) {
211	        lines.push(`      Topics: ${m.topics.map((t) => t.title).join('; ')}`);
212	      }
213	      if (m.lessonTasks && m.lessonTasks.length > 0) {
214	        lines.push(
215	          `      Tasks: ${m.lessonTasks.map((t) => t.title).join('; ')}`,
216	        );
217	      }
218	      if (m.endorsements && m.endorsements.length > 0) {
219	        lines.push(
220	          `      Endorsements: ${m.endorsements.map((e) => `${e.code} - ${e.title}`).join('; ')}`,
221	        );
222	      }
223	      if (m.regulations && m.regulations.length > 0) {
224	        lines.push(
225	          `      Regulations: ${m.regulations.map((r) => `${r.part} §${r.section}`).join('; ')}`,
226	        );
227	      }
228	    }
229	    lines.push('');
230	  }
231	
232	  return lines.join('\n');
233	}
