243	function extractJson(text: string): unknown {
244	  let cleaned = text.trim();
245	  if (cleaned.startsWith('```')) {
246	    cleaned = cleaned.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
247	  }
248	  // Handle case where JSON starts after some text
249	  const jsonStart = cleaned.indexOf('{');
250	  if (jsonStart > 0) {
251	    cleaned = cleaned.slice(jsonStart);
252	  }
253	  // safeParseAIJson attempts repair if the response was truncated (e.g. max_tokens reached)
254	  return safeParseAIJson(cleaned);
255	}
