535	                max_tokens: 8192,
536	                stream: true,
537	                messages: [{ role: 'user', content: prompt }],
538	              }),
539	              signal: abortSignal,
540	            },
541	          );
542	
543	          if (!anthropicRes.ok) {
544	            const errBody = await anthropicRes.text().catch(() => '');
545	            emit({
546	              type: 'error',
547	              error: `API error ${anthropicRes.status}: ${errBody}`,
548	            });
549	            safeClose();
550	            return;
551	          }
552	
553	          const reader = anthropicRes.body?.getReader();
554	          if (!reader) {
555	            emit({ type: 'error', error: 'No response body from AI' });
556	            safeClose();
557	            return;
558	          }
559	
560	          const decoder = new TextDecoder();
561	          let buf = '';
562	
563	          while (!closed) {
