565	            if (done) break;
566	
567	            buf += decoder.decode(value, { stream: true });
568	            const lines = buf.split('\n');
569	            buf = lines.pop() ?? '';
570	
571	            for (const line of lines) {
572	              if (!line.startsWith('data: ')) continue;
573	              const raw = line.slice(6).trim();
574	              if (raw === '[DONE]') continue;
575	
576	              let parsed: Record<string, unknown>;
577	              try {
578	                parsed = JSON.parse(raw) as Record<string, unknown>;
579	              } catch {
580	                continue;
581	              }
582	
583	              if (parsed.type === 'content_block_delta') {
584	                const delta = parsed.delta as
585	                  | { type?: string; text?: string }
586	                  | undefined;
587	                if (delta?.type === 'text_delta' && delta.text) {
588	                  emit({ type: 'chunk', text: delta.text });
589	                }
590	              } else if (parsed.type === 'message_stop') {
591	                emit({ type: 'done' });
592	              }
593	            }
594	          }
595	        } catch (err) {
596	          if (!abortSignal?.aborted) {
597	            const msg =
598	              err instanceof Error
599	                ? err.message
600	                : typeof err === 'object' && err !== null
601	                  ? JSON.stringify(err)
602	                  : String(err);
603	            emit({ type: 'error', error: msg });
604	          }
605	        } finally {
606	          clearInterval(heartbeat);
607	          safeClose();
608	        }
609	      },
610	    });
611	
612	    return new Response(stream, {
613	      headers: {
614	        'Content-Type': 'text/event-stream',
615	        'Cache-Control': 'no-cache',
616	        'X-Accel-Buffering': 'no',
617	      },
618	    });
619	  },
620	);
