66	async function callClaude(
67	  apiKey: string,
68	  prompt: string,
69	  maxTokens: number,
70	): Promise<{ text: string; inputTokens: number; outputTokens: number }> {
71	  const response = await fetch('https://api.anthropic.com/v1/messages', {
72	    method: 'POST',
73	    headers: {
74	      'Content-Type': 'application/json',
75	      'x-api-key': apiKey,
76	      'anthropic-version': '2023-06-01',
77	    },
78	    body: JSON.stringify({
79	      model: ANTHROPIC_MODEL,
80	      max_tokens: maxTokens,
81	      messages: [{ role: 'user', content: prompt }],
82	    }),
83	  });
84	
85	  if (!response.ok) {
86	    const errBody = await response.text();
87	    throw new Error(`Claude API error ${response.status}: ${errBody}`);
88	  }
89	
90	  const data = (await response.json()) as {
91	    content?: Array<{ type: string; text?: string }>;
92	    usage?: { input_tokens?: number; output_tokens?: number };
93	    error?: { message?: string };
94	  };
95	
96	  if (data.error) {
97	    throw new Error(
98	      `Claude API error: ${data.error.message ?? 'Unknown error'}`,
99	    );
100	  }
101	
102	  const text = data.content?.find((b) => b.type === 'text')?.text ?? '';
103	  return {
104	    text,
105	    inputTokens: data.usage?.input_tokens ?? 0,
106	    outputTokens: data.usage?.output_tokens ?? 0,
107	  };
108	}
