274	/**
275	 * POST /ai-curriculum/incremental/start
276	 *
277	 * Creates a new incremental build record, calls Claude to generate just the
278	 * stage outline (~10s), and returns the outline for admin review.
279	 * Fast enough to run synchronously — no background job needed.
280	 */
281	aiCurriculumIncremental.post(
282	  '/ai-curriculum/incremental/start',
283	  requireAuth(),
284	  async (c) => {
285	    const apiKey = getAnthropicKey('curriculum-incremental-add');
286	    if (!apiKey) {
287	      return c.json({ error: 'AI service not configured' }, 503);
288	    }
289	
290	    let params: BuilderParams;
291	    try {
292	      params = await c.req.json();
293	    } catch {
294	      return c.json({ error: 'Invalid request body' }, 400);
295	    }
296	
297	    if (
298	      !params.programType ||
299	      !params.regulatoryFramework ||
300	      !params.locationId
301	    ) {
302	      return c.json(
303	        {
304	          error:
305	            'programType, regulatoryFramework, and locationId are required',
306	        },
307	        400,
308	      );
309	    }
310	
311	    const authUser = c.get('authUser') as AuthUser;
312	    const orgId = await resolveOrgIdFromSession(authUser, c);
313	    if (!orgId) return c.json({ error: 'Could not resolve organization' }, 403);
314	
315	    // Cancel any existing in-progress builds for this location+user to prevent
316	    // orphaned builds accumulating.
317	    await db
318	      .update(curriculumIncrementalBuilds)
319	      .set({ status: 'cancelled', updatedAt: new Date() })
320	      .where(
321	        and(
322	          eq(curriculumIncrementalBuilds.flightSchoolId, orgId),
323	          eq(curriculumIncrementalBuilds.locationId, params.locationId),
324	          eq(curriculumIncrementalBuilds.userId, authUser.id),
325	          or(
326	            eq(curriculumIncrementalBuilds.status, 'outline_pending'),
327	            eq(curriculumIncrementalBuilds.status, 'outline_approved'),
328	          ),
329	        ),
330	      );
331	
332	    // Create the build record
333	    const [build] = await db
334	      .insert(curriculumIncrementalBuilds)
335	      .values({
336	        flightSchoolId: orgId,
337	        locationId: params.locationId,
338	        userId: authUser.id,
339	        status: 'outline_pending',
340	        builderParams: params as never,
341	        approvedStages: [],
342	        currentStageIdx: 0,
343	        totalStages: params.stageCount,
344	        saveAs: (params.saveAs as string) ?? 'draft',
345	      })
346	      .returning({ id: curriculumIncrementalBuilds.id });
347	
348	    // Generate outline synchronously (~10s)
349	    const prompt = buildOutlinePrompt(params);
350	    let aiResult: { text: string; inputTokens: number; outputTokens: number };
351	    try {
352	      aiResult = await callClaude(apiKey, prompt, 1024);
353	    } catch (err) {
354	      const msg =
355	        err instanceof Error
356	          ? err.message
357	          : typeof err === 'object' && err !== null
358	            ? JSON.stringify(err)
359	            : String(err);
360	      // Mark build as failed
361	      await db
362	        .update(curriculumIncrementalBuilds)
363	        .set({ status: 'cancelled', updatedAt: new Date() })
364	        .where(eq(curriculumIncrementalBuilds.id, build.id));
365	      return c.json({ error: `AI generation failed: ${msg}` }, 500);
366	    }
367	
368	    void recordAiTokenUsage({
369	      feature: 'curriculum_incremental_outline',
370	      flightSchoolId: orgId,
371	      inputTokens: aiResult.inputTokens,
372	      outputTokens: aiResult.outputTokens,
373	    });
374	
375	    const cleaned = stripCodeFences(aiResult.text);
376	    const parsed = safeParseAIJson<{ stages?: OutlineStage[] }>(cleaned);
377	
378	    if (
379	      !parsed ||
380	      !Array.isArray(parsed.stages) ||
381	      parsed.stages.length === 0
382	    ) {
383	      await db
384	        .update(curriculumIncrementalBuilds)
385	        .set({ status: 'cancelled', updatedAt: new Date() })
386	        .where(eq(curriculumIncrementalBuilds.id, build.id));
387	      return c.json(
388	        {
389	          error: 'AI returned an invalid outline structure — please try again',
390	        },
391	        500,
392	      );
393	    }
394	
395	    const outline: GeneratedOutline = { stages: parsed.stages };
396	
397	    // Persist outline to DB
398	    await db
399	      .update(curriculumIncrementalBuilds)
400	      .set({
401	        outline: outline as never,
402	        totalStages: outline.stages.length,
403	        updatedAt: new Date(),
404	      })
405	      .where(eq(curriculumIncrementalBuilds.id, build.id));
406	
407	    return c.json({ buildId: build.id, outline });
408	  },
409	);
