185	function computeStageHours(stage: ExportStage): {
186	  flight: number;
187	  ground: number;
188	  sim: number;
189	} {
190	  let flight = 0;
191	  let ground = 0;
192	  let sim = 0;
193	  for (const m of stage.modules) {
194	    const dur = Number(m.duration) || 0;
195	    const pre = Number(m.preBrief) || 0;
196	    const deb = Number(m.debrief) || 0;
197	    const et = (m.eventType || '').toLowerCase();
198	    if (
199	      et.includes('flight') ||
200	      et === 'stage check' ||
201	      et === 'practical test'
202	    ) {
203	      flight += dur;
204	    } else if (et.includes('ground')) {
205	      ground += dur;
206	    } else if (et.includes('sim') || et.includes('simulator')) {
207	      sim += dur;
208	    } else {
209	      flight += dur;
210	    }
211	    ground += pre + deb;
212	  }
213	  return { flight, ground, sim };
214	}
