216	function buildCurriculumPrompt(input: ExportCurriculumInput): string {
217	  const certificateRating =
218	    input.certificateRatingName || input.category || 'Not specified';
219	  const lines: string[] = [
220	    `CURRICULUM: ${input.title}`,
221	    `Certificate / Rating: ${certificateRating}`,
222	    `ACS Key: ${input.certificateRatingAcsKey || 'Not specified'}`,
223	    `Level: ${input.level || 'Not specified'}`,
224	    `Description: ${input.description || 'None'}`,
225	    `Total Flight Hours: ${input.flightHours}`,
226	    `Total Ground Hours: ${input.groundHours}`,
227	    `Total Sim Hours: ${input.simHours}`,
228	    `Total Stages: ${input.stages.length}`,
229	    '',
230	  ];
231	
232	  for (const [si, stage] of input.stages.entries()) {
233	    lines.push(`STAGE ${si + 1}: ${stage.name}`);
234	    if (stage.description) lines.push(`  Description: ${stage.description}`);
235	    lines.push(`  Modules (${stage.modules.length}):`);
236	    for (const [mi, m] of stage.modules.entries()) {
237	      lines.push(
238	        `    Module ${mi + 1}: [${m.moduleType}] ${m.title} (${m.eventType || 'Lesson'}, ${m.duration}min + ${m.preBrief}min pre + ${m.debrief}min debrief)`,
239	      );
240	      if (m.description) lines.push(`      Description: ${m.description}`);
241	      if (m.lessonTasks?.length) {
242	        lines.push(
243	          `      Lesson Tasks: ${m.lessonTasks.map((t) => t.title).join(' | ')}`,
244	        );
245	      }
246	      if (m.topics?.length) {
247	        lines.push(`      Topics: ${m.topics.map((t) => t.title).join(' | ')}`);
248	      }
249	      if (m.regulations?.length) {
250	        lines.push(
251	          `      Regulations: ${m.regulations.map((r) => `${r.part} §${r.section}`).join(' | ')}`,
252	        );
253	      }
254	    }
255	    lines.push('');
256	  }
257	
258	  return lines.join('\n');
259	}
