261	function extractJson(text: string): unknown {
262	  let cleaned = text.trim();
263	  if (cleaned.startsWith('```')) {
264	    cleaned = cleaned.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
265	  }
266	  const jsonStart = cleaned.indexOf('{');
267	  if (jsonStart > 0) cleaned = cleaned.slice(jsonStart);
268	  return safeParseAIJson(cleaned);
269	}
