1	/**
2	 * Inngest function: Background AI curriculum generation.
3	 *
4	 * Triggered by 'curriculum/build.start' when an admin clicks "Build Complete
5	 * Curriculum". Runs the entire Claude generation server-side with no browser
6	 * session dependency — page refreshes cannot kill this job.
7	 *
8	 * Progress is written to curriculum_build_jobs after each step so the frontend
9	 * polling endpoint (GET /ai-curriculum/build-status/:jobId) can report it.
10	 *
11	 * Architecture:
12	 *   1. POST /ai-curriculum/build  → creates job, sends event, returns {jobId}
13	 *   2. This function             → runs generation, writes progress + result
14	 *   3. Client polls build-status → shows progress banner until complete
15	 */
16	
17	import { aiGateway } from '@/lib/ai-control-center';
18	import { db } from '@/lib/db';
19	import {
20	  addCurriculumIds,
21	  callClaudeStreaming,
22	  safeParseAIJson,
23	} from '@/lib/import/helpers';
24	import { curriculumBuildJobs } from '@/lib/schema';
25	import {
26	  type BuilderParams,
27	  type GeneratedCurriculum,
28	  buildCurriculumPrompt,
29	  buildFallbackSummary,
30	  computeHoursFromStages,
31	  stripCodeFences,
32	} from '@/server/routes/routes-ai-curriculum-builder';
33	import { recordAiTokenUsage } from '@/server/routes/routes-integration-usage';
34	import { eq } from 'drizzle-orm';
35	import { inngest } from '../client';
36	
37	// Maximum allowed duration for the entire build.
38	const JOB_TIMEOUT = '10m';
39	
40	// ─── Progress steps ────────────────────────────────────────────────────────────
41	
42	const STEPS = {
43	  analyzing: { label: 'Analyzing FAA requirements', pct: 5 },
44	  structuring: { label: 'Building curriculum structure', pct: 15 },
45	  generating: { label: 'Generating curriculum content', pct: 20 },
46	  parsing: { label: 'Parsing and validating result', pct: 90 },
47	  saving: { label: 'Saving completed curriculum', pct: 95 },
48	} as const;
49	
50	async function setProgress(jobId: string, label: string, pct: number) {
51	  await db
52	    .update(curriculumBuildJobs)
53	    .set({ progressStep: label, progressPct: pct })
54	    .where(eq(curriculumBuildJobs.id, jobId));
55	}
56	
57	// ─── Inngest function ─────────────────────────────────────────────────────────
58	
59	export const curriculumBuilder = inngest.createFunction(
60	  {
61	    id: 'curriculum-builder',
62	    concurrency: [{ limit: 5 }],
63	    retries: 0, // Generation is expensive — do not auto-retry on failure
64	    timeouts: { finish: JOB_TIMEOUT },
65	    triggers: [{ event: 'curriculum/build.start' as const }],
66	  },
67	  async ({
68	    event,
69	    step,
70	  }: {
71	    event: { data: { jobId: string } };
72	    step: { run: <T>(id: string, fn: () => Promise<T>) => Promise<T> };
73	  }) => {
74	    const { jobId } = event.data;
75	
76	    // 1. Load the job record
77	    const job = await step.run('load-job', async () => {
78	      const [row] = await db
79	        .select()
80	        .from(curriculumBuildJobs)
81	        .where(eq(curriculumBuildJobs.id, jobId))
82	        .limit(1);
83	      if (!row) throw new Error(`Build job ${jobId} not found`);
84	      return row;
85	    });
86	
87	    if (
88	      job.status === 'completed' ||
89	      job.status === 'failed' ||
90	      job.status === 'cancelled'
91	    ) {
92	      return { skipped: true, reason: `Job already ${job.status}` };
93	    }
94	
95	    // 2. Mark as building
96	    await step.run('mark-building', async () => {
97	      await db
98	        .update(curriculumBuildJobs)
99	        .set({
100	          status: 'building',
101	          startedAt: new Date(),
102	          progressStep: STEPS.analyzing.label,
103	          progressPct: STEPS.analyzing.pct,
104	        })
105	        .where(eq(curriculumBuildJobs.id, jobId));
106	    });
107	
108	    // 3. Generate the curriculum via Claude (entire build in one step)
109	    const result = await step.run('generate-curriculum', async () => {
110	      if (!aiGateway.isFeatureConfigured('curriculum.generator')) {
111	        throw new Error('ANTHROPIC_API_KEY not configured');
112	      }
113	
114	      const params = job.builderParams as BuilderParams;
115	
116	      await setProgress(jobId, STEPS.structuring.label, STEPS.structuring.pct);
117	      const prompt = buildCurriculumPrompt(params);
118	
119	      await setProgress(jobId, STEPS.generating.label, STEPS.generating.pct);
120	
121	      // Track char count for intermediate progress updates
122	      let lastUpdatePct: number = STEPS.generating.pct;
123	      const aiResult = await callClaudeStreaming(
124	        'curriculum.generator',
125	        [{ type: 'text', text: prompt }],
126	        32000,
127	        undefined,
128	        (_chunk, charCount) => {
129	          // Advance progress bar as tokens arrive (rough heuristic: ~120K chars = 100%)
130	          const newPct = Math.min(
131	            85,
132	            STEPS.generating.pct + Math.floor((charCount / 120000) * 65),
133	          );
134	          if (newPct >= lastUpdatePct + 5) {
135	            lastUpdatePct = newPct;
136	            void setProgress(jobId, STEPS.generating.label, newPct);
137	          }
138	        },
139	        { legacyFeature: 'inngest-curriculum-builder' },
140	      );
141	
142	      await setProgress(jobId, STEPS.parsing.label, STEPS.parsing.pct);
143	
144	      const cleaned = stripCodeFences(aiResult.text);
145	      const parsed = safeParseAIJson(cleaned) as {
146	        title?: string;
147	        description?: string;
148	        category?: string;
149	        stages?: unknown[];
150	        summary?: unknown;
151	      } | null;
152	
153	      if (!parsed || !parsed.stages || !Array.isArray(parsed.stages)) {
154	        throw new Error(
155	          'AI returned an invalid curriculum structure — please try again',
156	        );
157	      }
158	
159	      const stagesWithIds = addCurriculumIds(parsed.stages);
160	      const computedHours = computeHoursFromStages(stagesWithIds);
161	      const rawSummary =
162	        parsed.summary ?? buildFallbackSummary(stagesWithIds, params);
163	
164	      const curriculum: GeneratedCurriculum = {
165	        title: parsed.title ?? `${params.programType} Curriculum`,
166	        description:
167	          parsed.description ??
168	          `Complete ${params.regulatoryFramework} ${params.programType} curriculum`,
169	        category: parsed.category ?? params.programType,
170	        stages: stagesWithIds,
171	        summary: {
172	          ...(rawSummary as object),
173	          hours: computedHours,
174	        } as GeneratedCurriculum['summary'],
175	      };
176	
177	      void recordAiTokenUsage({
178	        feature: 'curriculum_builder',
179	        flightSchoolId: job.flightSchoolId,
180	        inputTokens: aiResult.inputTokens,
181	        outputTokens: aiResult.outputTokens,
182	      });
183	
184	      return { curriculum, wasTruncated: aiResult.wasTruncated };
185	    });
186	
187	    // 4. Mark complete and store the generated curriculum
188	    await step.run('mark-complete', async () => {
189	      await setProgress(jobId, STEPS.saving.label, STEPS.saving.pct);
190	      await db
191	        .update(curriculumBuildJobs)
192	        .set({
193	          status: 'completed',
194	          generatedCurriculum: result.curriculum as never,
195	          wasTruncated: result.wasTruncated,
196	          progressStep: 'Complete',
197	          progressPct: 100,
198	          completedAt: new Date(),
199	        })
200	        .where(eq(curriculumBuildJobs.id, jobId));
201	    });
202	
203	    return { jobId, status: 'completed' };
204	  },
205	);
