/** Strip markdown code fences from AI response, including when preamble text precedes the fence */
export function stripCodeFences(text: string): string {
  const s = text.trim();
  // Non-anchored match so preamble text ("Here is the JSON: ```json {...} ```") is handled
  const fenceMatch = s.match(/```(?:\w+)?\n?([\s\S]*?)\n?```/);
  if (fenceMatch?.[1]) {
    return fenceMatch[1].trim();
  }
  return s;
}

